/**
 * dsh-lan-proxy — 转发核心（src/server/proxy/impl/proxy.ts）结构化单测。
 *
 * 覆盖本批未覆盖热点：
 * - bridgeCompressedWs：WebSocket 压缩桥接（真实 WS 连接，全 localhost，无外网）
 * - createLanProxy 转发错误处理（不可达上游 → 502，proxy error 分支）
 * - createLanProxy HTTPS 降级（HTTPS 端口被占 → HTTP-only）
 * - createLanProxy 围栏与参数校验（非回环 targetHost / 非法 targetPort）
 * - 纯函数边界用例（hostnameAllowed / isLoopbackTarget / formatAuthority /
 *   rewriteHeaders / compressWsPath / isCompressible / resolveCompressionOptions）
 *
 * 本文件由脚本式断言迁为 vitest 结构化用例（#722 阶段 1）：原每条 assert 对应一个
 * it，判定口径与断言集合均未改动。真实端口相关块以 beforeAll 包住原有 setup/观测
 * 序列、afterAll 回收句柄——每个 it 只做断言，操作顺序与原脚本逐行一致；端口一律
 * 沿用原动态分配（listen(0) / 占位服务器取端口），未引入任何固定端口。
 */
import { beforeAll, describe, expect, it } from "vitest";
import { createServer, request as httpRequest } from "node:http";
import type { AddressInfo } from "node:net";
import type { IncomingHttpHeaders } from "node:http";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHash } from "node:crypto";
import { constants as zlibConstants } from "node:zlib";
import { WebSocket as WsClient, WebSocketServer } from "ws";

// 单元层导入面（ARCHITECTURE-METHOD §8）：同域白盒直连 impl，不经包 barrel——
// 经 barrel 会把内部符号钉在包导出面上，让「包 ABI 收窄」永远被测试消费方挡住。
import {
  hostnameAllowed,
  formatAuthority,
  rewriteHeaders,
  bridgeUpstreamHeaders,
  createLanProxy,
  compressWsPath,
  isCompressible,
  resolveCompressionOptions,
  deflateAllowedByPolicy,
  hasDshAuthCookie,
  isTokenMintCandidate,
  withLaunchToken,
} from "../../src/server/proxy/impl/proxy.ts";
import { isLoopbackTarget } from "../../src/server/shared/net.ts";
import { DEFAULT_OPTIONS } from "../../src/server/shared/defaults.ts";
import { DEFAULT_DEFLATE_POLICY } from "../../src/server/shared/deflate.ts";
import { ensureSelfSignedTls } from "../../src/server/tls/impl/index.ts";
import { DEFAULT_WSS_COMPRESS_PATHS } from "../../src/server/config/impl/model.ts";

const sleep = (ms: number): Promise<void> => new Promise<void>((r) => setTimeout(r, ms));

/** 轮询等待条件成立（防 flake 纪律：替代固定 sleep 猜时序）；超时返回 false。 */
async function waitFor(predicate: () => boolean, deadlineMs = 5000, stepMs = 20) {
  const start = Date.now();
  while (!predicate()) {
    if (Date.now() - start > deadlineMs) return false;
    await sleep(stepMs);
  }
  return true;
}

/** RFC6455 握手应答行（Sec-WebSocket-Accept 计算；供 raw 假对端完成升级）。 */
const wsHandshakeResponse = (key: string) =>
  "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n" +
  `Sec-WebSocket-Accept: ${createHash("sha1")
    .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
    .digest("base64")}\r\n\r\n`;

/** 起一个 WS 回显上游（wsBridge 三态用例共用）。 */
async function mkUpstream() {
  const upServer = createServer();
  const wss = new WebSocketServer({ noServer: true });
  upServer.on("upgrade", (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      ws.on("message", (data, isBinary) => ws.send(data, { binary: isBinary }));
    });
  });
  await new Promise<void>((r) => upServer.listen(0, "127.0.0.1", () => r()));
  const upPort = (upServer.address() as AddressInfo).port;
  return { upPort, upServer, wss };
}

/** 经代理建一条 WS 连接、等 open、重试发送帧至回显（上游段 open 竞态：桥接的
 *  浏览器段 message 监听在 upstreamWs open 后才挂载，过早帧会被丢——重试规避），
 *  关闭连接返回收到的帧。 */
async function openAndEcho(port: number, path: string): Promise<string[]> {
  const ws = new WsClient(`ws://127.0.0.1:${port}${path}`);
  const received: string[] = [];
  ws.on("message", (data) => received.push(data.toString()));
  await new Promise((r, j) => {
    ws.on("open", r);
    ws.on("error", j);
  });
  for (let i = 0; i < 6; i++) {
    ws.send(`ping-${path}-${i}`);
    if (await waitFor(() => received.length > 0, 800)) break;
  }
  ws.close();
  await sleep(100);
  return received;
}

