  it("scope 冲突 409 复用“被其他窗口修改”文案 + temp 已清", async () => {
    const scope = makeScope({}, { code: "SETTINGS_CONFLICT" });
    const { deps } = makeDeps({ config: scope.deps });
    const r = await callAction(deps, { body: { expectedRevision: 1 } });
